import{_ as t,o as a,c as n,a6 as s}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"内容协商","description":"Accept 系列字段、qvalue 语法、媒体范围优先级规则与 Vary 的缓存含义。","frontmatter":{"title":"内容协商","description":"Accept 系列字段、qvalue 语法、媒体范围优先级规则与 Vary 的缓存含义。","source":"https://daiw.org/manual/http11/content-negotiation"},"headers":[],"relativePath":"manual/computer-programming/http11/content-negotiation.md","filePath":"manual/computer-programming/http11/content-negotiation.md"}'),o={name:"manual/computer-programming/http11/content-negotiation.md"};function i(c,e,d,l,r,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="内容协商" tabindex="-1">内容协商 <a class="header-anchor" href="#内容协商" aria-label="Permalink to &quot;内容协商&quot;">​</a></h1><h2 id="qvalue" tabindex="-1">qvalue <a class="header-anchor" href="#qvalue" aria-label="Permalink to &quot;qvalue&quot;">​</a></h2><p>所有协商字段共用的权重语法：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weight = OWS &quot;;&quot; OWS &quot;q=&quot; qvalue</span></span>
<span class="line"><span>qvalue = ( &quot;0&quot; [ &quot;.&quot; 0*3DIGIT ] ) / ( &quot;1&quot; [ &quot;.&quot; 0*3(&quot;0&quot;) ] )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>硬性约束：</p><ul><li>取值范围 <strong>0–1</strong>，<strong>最多三位小数</strong>。<code>q=0.3333</code> 非法，<code>q=1.5</code> 非法。</li><li>缺省为 <strong><code>q=1</code></strong>。</li><li><strong><code>q=0</code> 表示「不可接受」</strong>，不是「最低优先级」——服务端不得返回该项。</li><li>参数名 <code>q</code> 大小写不敏感。</li><li><code>q</code> 是<strong>分隔符</strong>：<code>q</code> 之前的参数属于媒体类型本身，之后的属于扩展。<code>text/html;level=1;q=0.5;ext=x</code> 中 <code>level</code> 是类型参数，<code>ext</code> 是扩展参数。</li></ul><h2 id="accept" tabindex="-1">Accept <a class="header-anchor" href="#accept" aria-label="Permalink to &quot;Accept&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept      = #( media-range [ weight ] )</span></span>
<span class="line"><span>media-range = ( &quot;*/*&quot; / ( type &quot;/*&quot; ) / ( type &quot;/&quot; subtype ) ) parameters</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept: text/html, application/xhtml+xml, application/xml;q=0.9, */*;q=0.8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="优先级规则-必须按此顺序判定" tabindex="-1">优先级规则（必须按此顺序判定） <a class="header-anchor" href="#优先级规则-必须按此顺序判定" aria-label="Permalink to &quot;优先级规则（必须按此顺序判定）&quot;">​</a></h3><p><strong>特异性优先于 q 值</strong>——这是最常被实现错的地方：</p><ol><li><code>type/subtype</code> <strong>带参数</strong> 最具体</li><li><code>type/subtype</code></li><li><code>type/*</code></li><li><code>*/*</code> 最不具体</li></ol><p>只有在特异性<strong>相同</strong>时才比较 q 值。例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept: text/*;q=0.9, text/html;q=0.5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>对 <code>text/html</code> 而言，匹配的是 <code>text/html;q=0.5</code>（更具体），<strong>不是</strong> <code>q=0.9</code>。结果权重 0.5。</p><h3 id="缺省与空值" tabindex="-1">缺省与空值 <a class="header-anchor" href="#缺省与空值" aria-label="Permalink to &quot;缺省与空值&quot;">​</a></h3><ul><li>字段<strong>缺失</strong> = <code>*/*</code>，接受任何类型。</li><li>字段<strong>存在但为空</strong> = 不接受任何类型（合法但无意义）。</li><li>无可接受表示时，服务端 <strong>MAY</strong> 返回 <code>406</code>，也 <strong>MAY</strong> 忽略协商直接返回首选表示——后者在实践中更常见。</li></ul><h2 id="accept-encoding" tabindex="-1">Accept-Encoding <a class="header-anchor" href="#accept-encoding" aria-label="Permalink to &quot;Accept-Encoding&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept-Encoding = #( codings [ weight ] )</span></span>
<span class="line"><span>codings         = content-coding / &quot;identity&quot; / &quot;*&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept-Encoding: gzip, br;q=1.0, *;q=0.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>特殊规则：</p><ul><li><strong>字段缺失</strong> → 服务端可用任意编码（实践中应发不压缩的）。</li><li><strong>字段存在但为空</strong> → 只接受 <code>identity</code>（不编码）。</li><li><code>identity</code> <strong>始终可接受</strong>，除非显式 <code>identity;q=0</code>。</li><li><code>Accept-Encoding: identity;q=0, *;q=0</code> → 无任何可接受编码 → <code>406</code>。</li><li><code>*</code> 匹配所有<strong>未在字段中显式列出</strong>的编码。</li></ul><p>服务端选择了非 <code>identity</code> 编码时，响应 <strong>MUST</strong> 带 <code>Content-Encoding</code> 与 <code>Vary: Accept-Encoding</code>。</p><h2 id="accept-language" tabindex="-1">Accept-Language <a class="header-anchor" href="#accept-language" aria-label="Permalink to &quot;Accept-Language&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept-Language = #( language-range [ weight ] )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>language-range</code> 语法见 RFC 4647，大小写不敏感：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept-Language: zh-CN, zh;q=0.9, en;q=0.8, *;q=0.5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>匹配算法两种，服务端自选：</p><ul><li><strong>Basic filtering</strong>：范围 <code>zh</code> 匹配 <code>zh</code>、<code>zh-CN</code>、<code>zh-Hans-CN</code>（按 <code>-</code> 前缀逐段匹配），但不匹配 <code>zho</code>。</li><li><strong>Lookup</strong>：逐段截断寻找最佳单一匹配（<code>zh-Hans-CN</code> → <code>zh-Hans</code> → <code>zh</code>），配 <code>*</code> 作兜底。</li></ul><p>注意：语言标签的<strong>子标签数量不影响特异性排序</strong>——排序只看 q 值，与 <code>Accept</code> 的规则不同。</p><h2 id="accept-charset-已废弃" tabindex="-1">Accept-Charset（已废弃） <a class="header-anchor" href="#accept-charset-已废弃" aria-label="Permalink to &quot;Accept-Charset（已废弃）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept-Charset = #( ( token / &quot;*&quot; ) [ weight ] )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>RFC 9110 <strong>明确废弃</strong>该字段：绝大多数场景应统一用 UTF-8，逐请求协商字符集弊大于利。</p><ul><li>客户端 <strong>SHOULD NOT</strong> 再发送。</li><li>服务端 <strong>SHOULD</strong> 忽略。</li><li>保留定义仅为兼容历史实现。</li></ul><h2 id="vary" tabindex="-1">Vary <a class="header-anchor" href="#vary" aria-label="Permalink to &quot;Vary&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vary = #( &quot;*&quot; / field-name )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>响应</strong>字段。声明服务端在选择本表示时<strong>使用了哪些请求字段</strong>，是内容协商与缓存正确性的桥梁。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vary: Accept-Encoding, Accept-Language</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>缓存规则：</p><ul><li>缓存<strong>必须</strong>在后续请求的这些字段值与已存储请求<strong>相符</strong>时才可复用该响应。</li><li><code>Vary: *</code> → 该响应<strong>永不可</strong>被缓存复用（等价于不可缓存）。</li><li>字段名大小写不敏感。</li><li><strong>遗漏 <code>Vary</code> 是严重 bug</strong>：CDN 会把 gzip 版发给不支持 gzip 的客户端，或把中文版发给英文用户。</li><li>值列得<strong>过多</strong>同样有害：每多一个字段，缓存命中率按其取值组合数下降。<code>Vary: User-Agent</code> 几乎等于禁用缓存。</li></ul><h3 id="与内容协商的配对" tabindex="-1">与内容协商的配对 <a class="header-anchor" href="#与内容协商的配对" aria-label="Permalink to &quot;与内容协商的配对&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用了什么协商</th><th>必须发的 Vary</th></tr></thead><tbody><tr><td>按 <code>Accept-Encoding</code> 压缩</td><td><code>Vary: Accept-Encoding</code></td></tr><tr><td>按 <code>Accept-Language</code> 选语言</td><td><code>Vary: Accept-Language</code></td></tr><tr><td>按 <code>Accept</code> 选格式</td><td><code>Vary: Accept</code></td></tr><tr><td>按 <code>Authorization</code> 定制</td><td><code>Vary: Authorization</code>（且通常需 <code>private</code>）</td></tr><tr><td>按 Cookie 定制</td><td><code>Vary: Cookie</code>（命中率极低，宜改用 <code>private</code>）</td></tr></tbody></table><h2 id="主动式-vs-响应式协商" tabindex="-1">主动式 vs 响应式协商 <a class="header-anchor" href="#主动式-vs-响应式协商" aria-label="Permalink to &quot;主动式 vs 响应式协商&quot;">​</a></h2><ul><li><strong>主动式（proactive）</strong>：服务端按 <code>Accept-*</code> 选表示。即本篇全部内容。缺点是客户端偏好未必准确、<code>Vary</code> 拖累缓存。</li><li><strong>响应式（reactive）</strong>：服务端返回 <code>300</code> 列出可选项，客户端自选。多一轮往返，实际几乎不用。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/http-date">日期与时间</a>——HTTP-date 的三种格式与 Date 字段规则。</p>`,45)])])}const h=t(o,[["render",i]]);export{g as __pageData,h as default};
